int main(void){pr_closures_init();for(int i=0;i<2;i++){pr_rng r=constructor_states[i];CHECK((uint32_t)floor(pr_rng_real_in_range(&r,0,4294967296.0))==command_actors[0].id);}bt.game_mode=GAME_MODES_CLASSIC;bt.wave_index=bt.turn=1;bt.double_battle=true;bt.ignoring_effect_source=-1;bt.rng=command_before[0];bt.battle_rng=command_before[1];bt.rng_live=bt.battle_rng_live=true;pr_seed_from_ascii(&bt.wave_seed,"turn-actor-wave");bt.n_party[0]=bt.n_party[1]=2;for(int k=0;k<4;k++){pr_pokemon*p=&mons[k];pr_reset_turn_data(p);p->id=command_actors[k].id;p->species=command_actors[k].species;p->form=command_actors[k].form;p->level=command_actors[k].level;p->hp=command_actors[k].hp;memcpy(p->stats,command_actors[k].stats,sizeof p->stats);for(int s=0;s<7;s++)p->stat_stages[s]=command_actors[k].stages[s];memset(p->ivs,15,6);p->nature=0;p->friendship=70;p->ability=p->base_ability=p->custom_ability=ABILITY_ID_NONE;p->ability_override=-1;p->tera_type=p->added_type=-1;p->on_field=true;p->is_player=k<2;p->n_moves=3;p->moves[0]=MOVE_ID_FUSION_FLARE;p->moves[1]=MOVE_ID_FUSION_BOLT;p->moves[2]=MOVE_ID_SPLASH;for(int m=0;m<4;m++)p->max_pp_override[m]=-1;bt.field[k]=bt.party[k/2][k%2]=p;bt.commands[k]=(struct pr_turn_command){.command=COMMAND_FIGHT,.move=k==0?MOVE_ID_FUSION_FLARE:k==1?MOVE_ID_FUSION_BOLT:MOVE_ID_SPLASH,.n_targets=1,.targets={k<2?2:k},.cursor=k==0?0:k==1?1:2,.use_mode=MOVE_USE_MODE_NORMAL};bt.pre_commands[k].command=-1;}pr_run_turn(&bt,&engine);CHECK(seen==1);CHECK(!engine.overflow&&!engine.events_overflow);uint32_t prior[2*PR_MAX_PARTY];bool complete=false;CHECK(!bt.n_last_turn_order);CHECK(pr_prior_turn_movers(&bt,prior,&complete)==0&&complete);printf("Actual colliding-ID Fusion turn: %d checks, %d mismatches/uncovered; trace%d events%d\n",checks,failures,engine.n_trace,engine.n_events);return failures?1:0;}
